// Generated by Flowshot from a HAR capture.
import { useState, type FormEvent } from 'react'
import { getNotes } from './api'
import type { GetNotesItem } from './api'

export function NotesSearch() {
  const [q, setQ] = useState("design")
  const [items, setItems] = useState<GetNotesItem[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    setLoading(true)
    setError('')
    try {
      const loaded = await getNotes({ q })
      setItems(loaded.items ?? [])
    } catch (caught) {
      setItems([])
      setError(caught instanceof Error ? caught.message : 'Request failed')
    } finally {
      setLoading(false)
    }
  }

  return (
    <form onSubmit={onSubmit}>
      <label>
        q
        <input value={q} onChange={(event) => setQ(event.target.value)} />
      </label>
      <button type="submit" disabled={loading}>{loading ? 'Loading…' : 'Run'}</button>
      {error ? <p role="alert">{error}</p> : null}
      <ul>
        {items.map((item) => (
          <li key={item.id}>
            <strong>{item.title}</strong>
            <div>{item.updatedAt}</div>
          </li>
        ))}
      </ul>
    </form>
  )
}
